import React, { useState, useEffect } from 'react';
import MessagesList from '../Pages/Messages/MessagesList';
import ChatWindow from '../Pages/Messages/ChatWindow';
import { MessageSquare, AlertCircle, Users, Plus, RefreshCw } from 'lucide-react';
import useMessages from '../../../hooks/useMessages';

const MessagesPage = ({ user }) => {
  const [showChat, setShowChat] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  const [showAdminList, setShowAdminList] = useState(false);
  const [availableAdmins, setAvailableAdmins] = useState([]);
  const [adminLoading, setAdminLoading] = useState(false);
  const { 
    conversations, 
    currentConversation, 
    messages,
    loading,
    error,
    fetchConversations,
    getOrCreateConversation,
    fetchMessages,
    sendMessage,
    fetchAdmins,
    fetchAvailableAdmins
  } = useMessages();

  // Utiliser l'utilisateur passé en props
  const userData = user;
  const isAdmin = userData?.role === 'admin';

  // Initialisation
  useEffect(() => {
    const init = async () => {
      try {
        await fetchConversations();
      } catch (error) {
        console.error('Erreur initialisation:', error);
      }
    };

    if (userData) {
      init();
    }
  }, [userData, fetchConversations]);

  const handleSelectConversation = async (conversation) => {
    setIsAnimating(true);

    try {
      await fetchMessages(conversation.id);
      setShowChat(true);
    } catch (error) {
      console.error('Erreur:', error);
    } finally {
      setIsAnimating(false);
    }
  };

  const handleSendMessage = async (conversationId, content) => {
    try {
      return await sendMessage(conversationId, content);
    } catch (error) {
      console.error('Erreur:', error);
      throw error;
    }
  };

  const handleCreateNewConversation = async (adminId) => {
    try {
      const conversation = await getOrCreateConversation(adminId);
      if (conversation) {
        await fetchMessages(conversation.id);
        setShowChat(true);
        setShowAdminList(false);
      }
    } catch (error) {
      console.error('Erreur:', error);
    }
  };

  const loadAvailableAdmins = async () => {
    try {
      setAdminLoading(true);
      const admins = await fetchAvailableAdmins();
      setAvailableAdmins(admins);
    } catch (error) {
      console.error('Erreur:', error);
    } finally {
      setAdminLoading(false);
    }
  };

  const handleRefresh = async () => {
    try {
      await fetchConversations();
    } catch (error) {
      console.error('Erreur:', error);
    }
  };

  // Rafraîchir périodiquement les conversations pour les admins
  useEffect(() => {
    if (isAdmin) {
      const interval = setInterval(() => {
        fetchConversations();
      }, 30000); // Toutes les 30 secondes

      return () => clearInterval(interval);
    }
  }, [isAdmin, fetchConversations]);

  // Vérifier si l'utilisateur est connecté
  if (!userData) {
    return (
      <div className="min-h-[80vh] flex items-center justify-center">
        <div className="text-center max-w-md p-8">
          <AlertCircle className="h-16 w-16 text-red-500 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-neutral-900 dark:text-white mb-3">
            Accès non autorisé
          </h1>
          <p className="text-neutral-600 dark:text-neutral-400 mb-6">
            Vous devez vous connecter pour accéder aux messages.
          </p>
          <button
            onClick={() => window.location.href = '/login'}
            className="px-6 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-lg hover:opacity-90 transition-opacity"
          >
            Se connecter
          </button>
        </div>
      </div>
    );
  }

  return (
    <>
      {/* Header */}
      <div className="mb-6 md:mb-8">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl md:text-3xl font-bold text-neutral-900 dark:text-white bg-gradient-to-r from-primary-600 to-secondary-600 bg-clip-text text-transparent">
                Messages {isAdmin ? '(Admin)' : ''}
              </h1>
              {isAdmin && (
                <button
                  onClick={handleRefresh}
                  className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
                  title="Rafraîchir"
                >
                  <RefreshCw className={`w-4 h-4 text-neutral-600 dark:text-neutral-400 ${loading ? 'animate-spin' : ''}`} />
                </button>
              )}
            </div>
            <p className="text-sm md:text-base text-neutral-600 dark:text-neutral-400 mt-1">
              {isAdmin ? 'Gérez les conversations des utilisateurs' : 'Discutez avec notre équipe de support'}
            </p>
          </div>
          <div className="flex items-center space-x-3">
            {!isAdmin && (
              <button
                onClick={() => {
                  loadAvailableAdmins();
                  setShowAdminList(true);
                }}
                className="px-4 py-2 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-lg hover:opacity-90 transition-opacity flex items-center gap-2 whitespace-nowrap"
                disabled={adminLoading}
              >
                {adminLoading ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
                    <span>Chargement...</span>
                  </>
                ) : (
                  <>
                    <Plus className="w-4 h-4" />
                    Nouvelle conversation
                  </>
                )}
              </button>
            )}
            <span className="px-3 py-1 text-xs font-medium bg-primary-100 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 rounded-full whitespace-nowrap">
              {conversations?.length || 0} conversation{conversations?.length !== 1 ? 's' : ''}
            </span>
          </div>
        </div>
      </div>

      {/* Afficher les erreurs */}
      {error && (
        <div className="mb-4 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg flex items-start gap-3 animate-fade-in">
          <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
          <div className="flex-1">
            <p className="text-red-600 dark:text-red-400 font-medium">Erreur</p>
            <p className="text-red-500 dark:text-red-300 text-sm mt-1">{error}</p>
            {error.includes('Session expirée') || error.includes('Veuillez vous reconnecter') ? (
              <button
                onClick={() => window.location.href = '/login'}
                className="mt-2 text-sm text-red-600 dark:text-red-400 hover:underline"
              >
                Se reconnecter
              </button>
            ) : (
              <button
                onClick={handleRefresh}
                className="mt-2 text-sm text-red-600 dark:text-red-400 hover:underline"
              >
                Réessayer
              </button>
            )}
          </div>
        </div>
      )}

      {/* Modal pour sélectionner un admin */}
      {showAdminList && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-neutral-900 rounded-2xl max-w-md w-full p-6 animate-slide-up">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-bold text-neutral-900 dark:text-white">
                Sélectionnez un conseiller
              </h3>
              <button
                onClick={() => setShowAdminList(false)}
                className="p-1 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg"
              >
                ✕
              </button>
            </div>

            {adminLoading ? (
              <div className="py-8 text-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500 mx-auto mb-3"></div>
                <p className="text-neutral-500">Chargement des conseillers...</p>
              </div>
            ) : availableAdmins.length === 0 ? (
              <div className="py-8 text-center">
                <Users className="h-12 w-12 text-neutral-400 mx-auto mb-3" />
                <p className="text-neutral-600 dark:text-neutral-400">
                  Aucun conseiller disponible pour le moment
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                {availableAdmins.map(admin => (
                  <button
                    key={admin.id}
                    onClick={() => handleCreateNewConversation(admin.id)}
                    className="w-full p-4 text-left border border-neutral-200 dark:border-neutral-800 rounded-xl hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors flex items-center gap-3"
                  >
                    <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold">
                      {admin.first_name?.charAt(0).toUpperCase() || 'A'}
                    </div>
                    <div className="flex-1">
                      <h4 className="font-medium text-neutral-900 dark:text-white">
                        {admin.first_name} {admin.last_name}
                      </h4>
                      <p className="text-sm text-neutral-500">Conseiller support</p>
                      {admin.conversation_count !== undefined && (
                        <p className="text-xs text-neutral-400">
                          {admin.conversation_count} conversation{admin.conversation_count !== 1 ? 's' : ''} en cours
                        </p>
                      )}
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Grid principale */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Liste des messages - Left Sidebar */}
        <div className={`lg:col-span-1 ${showChat ? 'hidden md:block' : 'block'}`}>
          <div className={`
            transition-all duration-500 ease-out
            ${isAnimating ? 'scale-95 opacity-50' : 'scale-100 opacity-100'}
          `}>
            <MessagesList 
              conversations={conversations}
              currentConversation={currentConversation}
              loading={loading}
              onSelectConversation={handleSelectConversation}
              isAdmin={isAdmin}
              user={userData}
            />
          </div>
        </div>

        {/* Fenêtre de chat - Right Content */}
        <div className={`lg:col-span-2 ${showChat ? 'block' : 'hidden md:block'}`}>
          <div className={`
            transition-all duration-500 ease-out
            ${isAnimating ? 'scale-95 opacity-50' : 'scale-100 opacity-100'}
          `}>
            {currentConversation ? (
              <ChatWindow 
                conversation={currentConversation}
                messages={messages}
                loading={loading}
                onSendMessage={handleSendMessage}
                onClose={() => setShowChat(false)}
                isAdmin={isAdmin}
                user={userData}
              />
            ) : (
              <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/40 dark:border-neutral-800/60 p-8 h-[600px] flex flex-col items-center justify-center relative overflow-hidden">
                {/* Background pattern */}
                <div className="absolute inset-0 bg-gradient-to-br from-primary-500/5 to-secondary-500/5"></div>

                {/* Content */}
                <div className="relative z-10 text-center max-w-md">
                  <div className="h-20 w-20 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center mx-auto mb-6 shadow-xl animate-float">
                    <MessageSquare className="h-10 w-10 text-white" />
                  </div>
                  <h3 className="text-2xl font-bold text-neutral-900 dark:text-white mb-3">
                    {isAdmin ? 'Panel Admin Messages' : 'Support Client'}
                  </h3>
                  <p className="text-neutral-600 dark:text-neutral-400 mb-6">
                    {loading 
                      ? 'Chargement des conversations...' 
                      : isAdmin 
                        ? 'Sélectionnez une conversation pour aider un utilisateur'
                        : 'Sélectionnez une conversation ou créez-en une nouvelle'
                    }
                  </p>

                  {!isAdmin && conversations?.length === 0 && !loading && (
                    <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4 mb-6">
                      <p className="text-blue-600 dark:text-blue-400 text-sm">
                        Vous n'avez pas encore de conversations. Cliquez sur "Nouvelle conversation" pour commencer.
                      </p>
                    </div>
                  )}

                  <div className="flex items-center justify-center space-x-4 text-sm text-neutral-500 dark:text-neutral-500">
                    <div className="flex items-center">
                      <div className="h-2 w-2 bg-green-500 rounded-full mr-2"></div>
                      <span>{conversations?.length || 0} conversation{conversations?.length !== 1 ? 's' : ''}</span>
                    </div>
                    {conversations?.some(c => c.unread_count > 0) && (
                      <div className="flex items-center">
                        <div className="h-2 w-2 bg-red-500 rounded-full mr-2"></div>
                        <span>{conversations.filter(c => c.unread_count > 0).length} non lu{conversations.filter(c => c.unread_count > 0).length !== 1 ? 's' : ''}</span>
                      </div>
                    )}
                  </div>

                  {!isAdmin && !loading && (
                    <button
                      onClick={() => {
                        loadAvailableAdmins();
                        setShowAdminList(true);
                      }}
                      className="mt-6 px-6 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-lg hover:opacity-90 transition-opacity flex items-center gap-2 mx-auto"
                    >
                      <Plus className="w-4 h-4" />
                      Nouvelle conversation
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

export default MessagesPage;
